"""English slide content; retain Vietnamese screenshot guidance and rehearsal text."""
from copy import deepcopy
from presentation_content import SLIDES as VI_SLIDES, PROTEGE_SHOTS as VI_SHOTS

SLIDES = deepcopy(VI_SLIDES)
PROTEGE_SHOTS = deepcopy(VI_SHOTS)
PHOTO_TITLES = ['Ontology IRI and version', 'Film class hierarchy', 'People and organizations',
                'Genre and award hierarchies', 'Contribution restrictions',
                'Domain, range, inverse and functional', 'Filmmaker definition',
                'FilmStudio cardinality', 'Runtime datatype', 'Inception individual',
                'Nolan asserted types']
for key, title in zip(PROTEGE_SHOTS, PHOTO_TITLES):
    PROTEGE_SHOTS[key]['title_en'] = title
for slide in SLIDES:
    slide['speech_vi'] = slide['speech']

def update(number, title, subtitle, speech, **content):
    SLIDES[number-1].update(title=title, subtitle=subtitle, speech=speech, section=title.split(' · ')[0], **content)

update(1, 'MovieLOD', 'Linked movie data application · Semantic Web',
       'Welcome. We present MovieLOD, a linked open data application for movies. The project connects a domain ontology, real source responses, RDF, external links and SPARQL queries. The current version contains 30 films, 42 declared classes and 1,727 external identity links. Inception and Christopher Nolan are our running examples. This deck has 24 slides. Vietnamese instructions remain inside the 11 empty Protégé screenshot slots so the team can add genuine evidence. These slots are placeholders, not screenshots. The demo video remains unchanged.')
update(2, 'Problem and five assignment requirements',
       'Who did what in which film? Where did the data come from? How can we query it?',
       'Movie data contains many related entities and overlapping roles. We want to identify Nolan’s roles in Inception, its production companies and the source of each claim. The five requirements form a workflow: define an ontology, collect real data, publish RDF with HTTP identifiers and an open license, link entities to external datasets, and provide SPARQL interfaces. Deliverables include a report of at most 15 pages, slides and a three-to-five-minute demo. The current video runs for about four minutes and fifty seconds.',
       rows=[['R1','Define an ontology','OWL/Turtle, classes, properties and restrictions'],['R2','Collect domain data','APIs, raw responses, URLs, timestamps and hashes'],['R3','Publish four-star data','RDF, HTTP IRIs, open license and publication'],['R4','Link to reach five stars','sameAs links, matching method and public data'],['R5','Provide SPARQL interfaces','Web application, endpoint and terminal']])
update(3, 'Architecture and data flow', 'Asserted data, schema and inferred types are stored separately',
       'The pipeline starts with the film list in config. collect.py fetches responses and stores provenance metadata. build.py creates the ontology and normalized RDF graph. validate.py checks application fields, source hashes and queries. reason.py writes additional types to a separate file. The local application uses Flask and RDFLib; the hosted application runs Comunica in the browser. The endpoint loads movies.ttl by default. The terminal --reasoned option also loads the schema and saved inferred types; it does not start a reasoner for every query. All RDF exports now use millisecond timestamps, while raw source metadata retains its original precision.',
       stages=[['01','COLLECT','Wikidata / DBpedia\ncollect.py → data/raw/'],['02','BUILD RDF','build.py → movies.ttl\n+ ontology/movie.ttl'],['03','VALIDATE','validate.py / pytest\nsources, fields and queries'],['04','CLASSIFY','reason.py →\ninferred_classes.ttl']])
